func newReversal() unsafe.Pointer { return unsafe.Pointer(new(journalreversal.Reversal)) }

func newNReversal(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]journalreversal.Reversal, n)))
}

func ptrReversal(p unsafe.Pointer, c int32) any {
	r := (*journalreversal.Reversal)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 2:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 3:
		return (*string)(unsafe.Pointer(&r.OriginalJournalEntryID))
	case 4:
		return (*string)(unsafe.Pointer(&r.ReversalJournalEntryID))
	case 5:
		return (*string)(unsafe.Pointer(&r.PostedBatchID))
	case 6:
		return (*string)(unsafe.Pointer(&r.Status))
	case 7:
		return &r.RequestedAccountingDate
	case 8:
		return (*string)(unsafe.Pointer(&r.ResolvedFiscalYearID))
	case 9:
		return (*string)(unsafe.Pointer(&r.ResolvedFiscalPeriodID))
	case 10:
		return &r.ReasonCode
	case 11:
		return &r.ReasonText
	case 12:
		return (*string)(unsafe.Pointer(&r.RequestedByID))
	case 13:
		return (*string)(unsafe.Pointer(&r.ApprovedByID))
	case 14:
		return &r.ApprovedAt
	case 15:
		return (*string)(unsafe.Pointer(&r.RejectedByID))
	case 16:
		return &r.RejectedAt
	case 17:
		return &r.RejectionReason
	case 18:
		return (*string)(unsafe.Pointer(&r.CancelledByID))
	case 19:
		return &r.CancelledAt
	case 20:
		return &r.CancelReason
	case 21:
		return (*string)(unsafe.Pointer(&r.PostedByID))
	case 22:
		return &r.PostedAt
	case 23:
		return &r.CreatedAt
	case 24:
		return &r.UpdatedAt
	case 25:
		return &r.Version
	}
	return nil
}

func valueReversal(p unsafe.Pointer, c int32) any {
	r := (*journalreversal.Reversal)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.OrganizationID)
	case 2:
		return string(r.BusinessUnitID)
	case 3:
		return string(r.OriginalJournalEntryID)
	case 4:
		if r.ReversalJournalEntryID == "" {
			return nil
		}
		return string(r.ReversalJournalEntryID)
	case 5:
		if r.PostedBatchID == "" {
			return nil
		}
		return string(r.PostedBatchID)
	case 6:
		return string(r.Status)
	case 7:
		return r.RequestedAccountingDate
	case 8:
		return string(r.ResolvedFiscalYearID)
	case 9:
		return string(r.ResolvedFiscalPeriodID)
	case 10:
		return r.ReasonCode
	case 11:
		return r.ReasonText
	case 12:
		return string(r.RequestedByID)
	case 13:
		if r.ApprovedByID == "" {
			return nil
		}
		return string(r.ApprovedByID)
	case 14:
		if r.ApprovedAt == nil {
			return nil
		}
		return *r.ApprovedAt
	case 15:
		if r.RejectedByID == "" {
			return nil
		}
		return string(r.RejectedByID)
	case 16:
		if r.RejectedAt == nil {
			return nil
		}
		return *r.RejectedAt
	case 17:
		if r.RejectionReason == "" {
			return nil
		}
		return r.RejectionReason
	case 18:
		if r.CancelledByID == "" {
			return nil
		}
		return string(r.CancelledByID)
	case 19:
		if r.CancelledAt == nil {
			return nil
		}
		return *r.CancelledAt
	case 20:
		if r.CancelReason == "" {
			return nil
		}
		return r.CancelReason
	case 21:
		if r.PostedByID == "" {
			return nil
		}
		return string(r.PostedByID)
	case 22:
		if r.PostedAt == nil {
			return nil
		}
		return *r.PostedAt
	case 23:
		return r.CreatedAt
	case 24:
		return r.UpdatedAt
	case 25:
		return r.Version
	}
	return nil
}

func attachReversal(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*journalreversal.Reversal)(p)
	switch rel {
	case 0:
		r.OriginalJournalEntry = (*journalentry.JournalEntry)(child)
	case 1:
		r.ReversalJournalEntry = (*journalentry.JournalEntry)(child)
	}
}

