func (c StatusCol) Eq(v journalreversal.Status) keel.Pred  { return c.StringCol.Eq(string(v)) }
func (c StatusCol) Ne(v journalreversal.Status) keel.Pred  { return c.StringCol.Ne(string(v)) }
